<?php

namespace Tests\Feature\Http\Controllers;

use App\Mail\MemberApp;
use App\Mail\MemberAppInterviewConfirmation;
use App\Models\FormSubmission;
use App\Models\FormSubmissionOutbox;
use App\Models\User;
use App\Services\Slack\KosBot;
use Database\Seeders\FormsTableSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Mail\MailManager;
use Illuminate\Support\Facades\Mail;
use Illuminate\Testing\TestResponse;
use Mockery\MockInterface;
use Tests\TestCase;

/**
 * The membership application: a special form (FormsTableSeeder, form 1, special_form new_user_app)
 * that a logged-in member fills in with a new applicant. Submitting it creates the applicant's
 * account, their first status, a form submission with an outbox entry for outside tools, the
 * notification emails and a Slack post in the applicants channel.
 *
 * Mail is faked (nothing is sent) and the Slack bot is replaced by a spy, so the tests never post
 * to the real Slack workspace and do not need a network connection.
 */
class FormsControllerTest extends TestCase
{
    use RefreshDatabase;

    private MailManager $mailerOriginal;

    private MockInterface $kosBot;

    /** Photos uploaded during a test, removed again afterwards. */
    private array $uploadedPhotos = [];

    /**
     * Uploads a photo the way the form's cropping tool does, then submits a complete, valid
     * application for a new applicant. Pass $overrides to change or blank out fields.
     */
    public function submitApplication(User $adminUser, $overrides = []): TestResponse
    {
        // upload photo
        $image = $this->actingAs($adminUser)->post('/image-crop/users', [
            'photo_type' => 'users',
            'id' => 'new',
            'image' => 'data:image/png;base64,',
        ]);

        $this->uploadedPhotos[] = $image->json('filename');

        return $this->actingAs($adminUser)->post('/forms/1/save',
            array_merge([
                'form_id' => 1,
                'element-cdf75849-ccb8-4cdf' => 'i',
                'first_name' => 'new',
                'last_name' => 'user',
                'email' => 'new@user.com',
                'phone' => '(123) 456-7890',
                'address' => 'some address',
                'city' => 'some city',
                'province' => 'AB',
                'postal' => 'A1A 1A1',
                'photo' => $image->json('filename'),
            ],
                $overrides));
    }

    protected function setUp(): void
    {
        parent::setUp();
        $this->seed(FormsTableSeeder::class);

        $this->mailerOriginal = Mail::getFacadeRoot();
        Mail::fake();

        $this->kosBot = $this->spy(KosBot::class);
    }

    /** @test */
    public function it_sends_a_confirmation_email_to_applicant_when_application_is_submitted()
    {
        $submittingUser = User::factory()->active()->create();

        $response = $this->submitApplication($submittingUser, [
            'first_name' => 'first',
            'last_name' => 'last',
            'email' => 'new@user.com',
        ]);

        $newUser = User::where('email', 'new@user.com')->first();

        $response->assertStatus(302);

        Mail::assertSent(MemberAppInterviewConfirmation::class, function (MemberAppInterviewConfirmation $mail) use ($newUser) {
            Mail::swap($this->mailerOriginal);
            $mail->assertTo($newUser->email);
            $mail->assertFrom('membership@kwartzlab.ca');
            $mail->assertHasSubject('Application Received - Kwartzlab Makerspace');
            $mail->assertSeeInOrderInHtml([
                $newUser->get_name(),
                config('kwartzlabos.membership_coordinator.name'),
                'Membership Coordinator',
                'membership@kwartzlab.ca',
            ]);

            return true;
        });
    }

    /**
     * Everything an application should create, checked in one place.
     *
     * Expects: a redirect back to the form with a success message, and:
     *  - an applicant account with today's date_applied, the uploaded photo and the given name;
     *  - one status history row, "applicant", made by kOS (updated_by 0);
     *  - a form submission linking the applicant and the member who filled it in, with the answers;
     *  - an outbox entry, so outside tools pick the application up.
     * Regression: date_applied used to be dropped silently (it was not mass-assignable).
     */
    public function test_submitting_an_application_creates_the_applicant()
    {
        $submittingUser = User::factory()->active()->create();

        $this->submitApplication($submittingUser, ['first_name' => 'Ada', 'last_name' => 'Lovelace', 'email' => 'ada@example.com'])
            ->assertRedirect('/forms/1')
            ->assertSessionHas('success', 'Application created & sent successfully.');

        $applicant = User::query()->where('email', 'ada@example.com')->sole();
        $this->assertSame('applicant', $applicant->status);
        $this->assertSame(now()->toDateString(), $applicant->date_applied->toDateString());
        $this->assertSame(end($this->uploadedPhotos), $applicant->photo);
        $this->assertSame('Ada Lovelace', $applicant->get_name());

        $status = $applicant->status_history()->sole();
        $this->assertSame(['applicant', 0], [$status->status, (int) $status->updated_by]);

        $submission = FormSubmission::query()->sole();
        $this->assertSame([$applicant->id, $submittingUser->id, 'new_user_app'], [(int) $submission->user_id, (int) $submission->submitted_by, $submission->special_form]);
        $this->assertSame('i', json_decode($submission->data, true)['cdf75849-ccb8-4cdf']['value']);
        $this->assertTrue(FormSubmissionOutbox::query()->where('form_submission_id', $submission->id)->exists());
    }

    /**
     * Members and the membership admins each get an email about a new applicant (members see less
     * contact information), and the applicant is announced in the Slack applicants channel.
     *
     * Expects: two MemberApp emails queued (one for members, one for admins) and one Slack post.
     */
    public function test_submitting_an_application_notifies_members_admins_and_slack()
    {
        $this->submitApplication(User::factory()->active()->create());

        Mail::assertQueued(MemberApp::class, 2);
        $this->kosBot->shouldHaveReceived('postNewAppplicantMessage')->once();
    }

    /**
     * Required questions are set per form (in the form's fields), plus the applicant details
     * every application needs (address and so on).
     *
     * Expects: form errors for a blank required question and a blank address, and no account
     * created.
     */
    public function test_an_application_needs_the_required_answers()
    {
        $this->submitApplication(User::factory()->active()->create(), ['element-cdf75849-ccb8-4cdf' => null, 'address' => null])
            ->assertSessionHasErrors(['element-cdf75849-ccb8-4cdf', 'address']);

        $this->assertFalse(User::query()->where('email', 'new@user.com')->exists());
    }

    /**
     * The applicant's email becomes their login and is where their notifications go, so an
     * application without one must be refused with a message the person filling it in can act on.
     *
     * Expects: a form error for a missing email, and no submission saved.
     * Regression: the email rule was never applied (a stray "break" skipped it), so this used to
     * fail with a database error (500) instead.
     */
    public function test_an_application_needs_an_email_address()
    {
        $this->submitApplication(User::factory()->active()->create(), ['email' => null])->assertSessionHasErrors('email');

        $this->assertSame(0, FormSubmission::query()->count());
    }

    protected function tearDown(): void
    {
        foreach (array_filter($this->uploadedPhotos) as $photo) {
            foreach (glob(public_path('storage/images/users/').$photo.'*') as $file) {
                unlink($file);
            }
        }
        parent::tearDown();
    }
}
